def predict(board, action):
    if isinstance(action, tuple):
        row, col = action
    else:
        row, col = action[0], action[1]

    char = board[row][col]
    if char == 'g':
        new_char = 'N'
    elif char == 'W':
        new_char = 'G'
    else:
        new_char = 'N' if char == 'b' else char

    board[row][col] = new_char

    if col > 0:
        board[row][col-1] = 'N' if board[row][col-1] == char else board[row][col-1]
    if col < 63:
        board[row][col+1] = 'N' if board[row][col+1] == char else board[row][col+1]
    if row > 0:
        board[row-1][col] = 'N' if board[row-1][col] == char else board[row-1][col]
    if row < 63:
        board[row+1][col] = 'N' if board[row+1][col] == char else board[row+1][col]

    return ["".join(row) for row in board]
